/// oauth API resource.
#[derive(Clone)]
pub struct OauthResource {
    client: Client,
}

impl OauthResource {
    /// Access the nested device resource.
    pub fn device(&self) -> OauthDeviceResource {
        OauthDeviceResource {
            client: self.client.clone(),
        }
    }
    /// List available OAuth scopes
    pub async fn scopes(&self) -> Result<GetOauthScopesResponse> {
        let path = "/oauth/scopes".to_owned();
        let request = self.client.request(Method::GET, &path);
        request.send().await
    }
    /// Blocking variant of [Self::scopes].
    #[cfg(feature = "blocking")]
    pub fn scopes_blocking(&self) -> Result<GetOauthScopesResponse> {
        crate::blocking::block_on(self.scopes())
    }
    /// Exchange a grant for OAuth tokens
    pub async fn token(&self, body: &PostOauthTokenInput) -> Result<OAuthTokenResponse> {
        let path = "/oauth/token".to_owned();
        let request = self.client.request(Method::POST, &path);
        let request = request.json(body)?;
        request.send().await
    }
    /// Blocking variant of [Self::token].
    #[cfg(feature = "blocking")]
    pub fn token_blocking(&self, body: &PostOauthTokenInput) -> Result<OAuthTokenResponse> {
        crate::blocking::block_on(self.token(body))
    }
}

/// device API resource.
#[derive(Clone)]
pub struct OauthDeviceResource {
    client: Client,
}

impl OauthDeviceResource {
    /// Approve a device authorization request
    pub async fn approve(
        &self,
        body: &PostOauthDeviceApproveInput,
    ) -> Result<DeviceAuthorizationStatusResponse> {
        let path = "/oauth/device/approve".to_owned();
        let request = self.client.request(Method::POST, &path);
        let request = request.json(body)?;
        request.send().await
    }
    /// Blocking variant of [Self::approve].
    #[cfg(feature = "blocking")]
    pub fn approve_blocking(
        &self,
        body: &PostOauthDeviceApproveInput,
    ) -> Result<DeviceAuthorizationStatusResponse> {
        crate::blocking::block_on(self.approve(body))
    }
    /// Inspect a pending device authorization
    pub async fn authorization(
        &self,
        params: &GetOauthDeviceAuthorizationParams,
    ) -> Result<DeviceAuthorizationDetailsResponse> {
        let path = "/oauth/device/authorization".to_owned();
        let request = self.client.request(Method::GET, &path);
        let request = request.query(params)?;
        request.send().await
    }
    /// Blocking variant of [Self::authorization].
    #[cfg(feature = "blocking")]
    pub fn authorization_blocking(
        &self,
        params: &GetOauthDeviceAuthorizationParams,
    ) -> Result<DeviceAuthorizationDetailsResponse> {
        crate::blocking::block_on(self.authorization(params))
    }
    /// Initiate a device authorization request
    pub async fn authorize(
        &self,
        body: &PostOauthDeviceAuthorizeInput,
    ) -> Result<DeviceAuthorizationResponse> {
        let path = "/oauth/device/authorize".to_owned();
        let request = self.client.request(Method::POST, &path);
        let request = request.json(body)?;
        request.send().await
    }
    /// Blocking variant of [Self::authorize].
    #[cfg(feature = "blocking")]
    pub fn authorize_blocking(
        &self,
        body: &PostOauthDeviceAuthorizeInput,
    ) -> Result<DeviceAuthorizationResponse> {
        crate::blocking::block_on(self.authorize(body))
    }
    /// Deny a device authorization request
    pub async fn deny(
        &self,
        body: &PostOauthDeviceDenyInput,
    ) -> Result<DeviceAuthorizationStatusResponse> {
        let path = "/oauth/device/deny".to_owned();
        let request = self.client.request(Method::POST, &path);
        let request = request.json(body)?;
        request.send().await
    }
    /// Blocking variant of [Self::deny].
    #[cfg(feature = "blocking")]
    pub fn deny_blocking(
        &self,
        body: &PostOauthDeviceDenyInput,
    ) -> Result<DeviceAuthorizationStatusResponse> {
        crate::blocking::block_on(self.deny(body))
    }
}
